/**
 * The P7 seed (src/backend/packages/seed/fcrm_seed/seed.json), imported at build time. It is generated by
 * gen_seed.py and never copied or edited here; Vite's fs.allow and tsconfig include point at it.
 * Only the mock backend reads it. The interface below types the parts the mocks use.
 */
import raw from '../../../backend/packages/seed/fcrm_seed/seed.json';

export type SeedDomain = 'customer' | 'product' | 'geography' | 'channel';

export interface SeedControlRating {
  id: string;
  rating: number | null;
  evidence: string;
  evidence_date?: string;
  stale?: boolean;
  planned?: boolean;
  note?: string;
  weight_norm?: number;
  override?: { from: number; to: number; by: string; reason: string };
}

export interface SeedArea {
  L: number;
  I: number;
  inherent: number;
  ce: number;
  retention: number;
  residual: number;
  weight: number;
  contribution: number;
  controls: SeedControlRating[];
}

export interface SeedScore {
  areas: Partial<Record<SeedDomain, SeedArea>>;
  composite: number;
  band: 1 | 2 | 3 | 4;
  route: 'analyst' | 'committee';
  boundary_flag: boolean;
  boundary_distance: number | null;
}

export interface SeedCase {
  id: string;
  title: string;
  unit: string;
  owner: string;
  analyst: string;
  change_types: string[];
  domains: SeedDomain[];
  created: string;
  submitted: string;
  decided: string | null;
  stage: 'closed' | 'under_assessment' | 'awaiting_business' | 'committee' | 'draft';
  outcome: 'approved' | 'approve_with_conditions' | 'deferred' | 'rejected' | null;
  fast_lane: boolean;
  inputs: Partial<Record<SeedDomain, { L: number; I: number; controls: SeedControlRating[] }>>;
  score: SeedScore;
  open_conditions: number;
  geographies: string[];
}

export interface SeedUser {
  id: string;
  name: string;
  role: string;
  unit?: string;
}

export interface SeedAuditRecord {
  n: number;
  type: string;
  by: string;
  what: string;
  scene: number;
}

export interface SeedDemo {
  id: string;
  title: string;
  short: string;
  unit: string;
  owner: string;
  analyst: string;
  change_types: string[];
  domains: SeedDomain[];
  documents: { name: string; pages: number; size_mb: number; candidates?: number; pii_masked?: number; added_in?: string }[];
  fields: { id: string; value: string | null; source?: string; how: string; candidates?: number; new_fact?: string }[];
  review_edit: { id: string; from: string; to: string; source_after: string; original_kept: string };
  required_fields: number;
  candidates_found: number;
  filled_by_extraction: number;
  filled_after_reuse: number;
  filled_at_submit: number;
  precedent: { id: string; similarity: number };
  precedents_closest: string[];
  clauses: { src: string; title: string; quote: string; ref: string; clause_id: string }[];
  clause_gap: string;
  score_before: SeedScore;
  score_after: SeedScore;
  critic_findings: { type: string; severity: 'high' | 'medium' | 'low'; text: string; records: string[] }[];
  completeness: { missing: string[]; stale: string[]; contradictory: string[]; questions_drafted: number; questions_kept: number };
  questions: { q: string; field?: string; a?: string; doc?: string; dropped?: string }[];
  recommendation: { outcome: string; edits_by_analyst: number; text: string };
  conditions: { id: string; text: string; owner: string; due: string; status: 'open' | 'scheduled'; from: string }[];
  committee_question: { from: string; q: string; a: string; by: string };
  votes: { member: string; vote: string; rationale?: string; rationale_words?: number }[];
  outcome: string;
  tally: Record<string, number>;
  versions: { scoring: string; corpus: string; controls: string; field_set: string; jurisdictions: string; routing: string; prompts: string };
  trace_id: string;
  audit: SeedAuditRecord[];
  examiner: { question: string; sentences: { t: string; refs: number[] }[] };
  audit_count: number;
  precedent_vdd_avg: number;
}

export interface Seed {
  meta: Record<string, string>;
  scoring_model: {
    version: string;
    owner: string;
    approved: string;
    likelihood_scale: Record<string, string>;
    impact_scale: Record<string, string>;
    retention_factor: number;
    retention_floor: number;
    domain_weights: Record<SeedDomain, number>;
    bands: { band: 1 | 2 | 3 | 4; min: number; max: number; route: 'analyst' | 'committee'; label: string }[];
    boundary_flag: number;
    rounding: string;
    planned_controls_scored: boolean;
  };
  domains: Record<SeedDomain, string>;
  change_types: Record<string, string>;
  type_domains: Record<string, SeedDomain[]>;
  field_set: {
    version: string;
    max_required: number;
    completion_threshold: number;
    always_required: { id: string; label: string; note?: string }[];
    per_type: Record<string, { id: string; label: string }[]>;
  };
  controls: { id: string; domain: SeedDomain; name: string; weight: number; evidence_artefact: string; last_tested: string }[];
  corpus: {
    version: string;
    ingested: string;
    sources: { id: string; title: string; kind: string; sections: string[]; used_for: string; clauses: number }[];
    clause_count: number;
  };
  jurisdictions: {
    current: {
      version: string;
      published: string;
      source: string;
      call_for_action: string[];
      increased_monitoring: string[];
      changes: { added: string[]; removed: string[] };
    };
    fixture: { version: string; fixture: boolean; note: string; added: string[]; removed: string[] };
  };
  agents: { name: string; tier: string; model: string; fallback: string; tools: string[]; skills: string[]; output: string; gate: string; eval_set: string }[];
  guards: { n: number; name: string; what: string }[];
  rules: string[];
  budgets: Record<string, { tokens_per_run: number; wall_s: number; retries: number } | number>;
  routing: { version: string; rules: { id: string; rule: string }[] };
  users: { po: SeedUser[]; analyst: SeedUser[]; committee: SeedUser[] };
  demo: SeedDemo;
  cases: SeedCase[];
  derived: {
    avg_days_intake_to_decision: number;
    closed_cases: number;
    po_active_cases: string[];
    po_open_conditions: number;
    analyst_open: Record<string, string[]>;
    band_distribution: Record<string, number>;
  };
  evals: {
    week: string;
    golden_cases: number;
    per_agent: Record<string, { metric: string; n?: number; correct?: number; pct: number; proposals?: number; overridden?: number }>;
    regressions: number;
    weekly_drift: string;
  };
}

export const seed = raw as unknown as Seed;

export const DEMO_ID = seed.demo.id;
